def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    colors = set()
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 0 and val != 2:
                colors.add(val)

    first_appearance = {}
    colors_ordered = []
    seen = set()
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 0 and val not in seen:
                seen.add(val)
                colors_ordered.append(val)
                first_appearance[val] = (r, c)

    color_locations = {c: set() for c in colors_ordered}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val in colors_ordered:
                color_locations[val].add((r, c))

    color_info = {}
    for c in colors_ordered:
        locs = list(color_locations[c])
        min_r = min(r for r,_ in locs)
        max_r = max(r for r,_ in locs)
        color_info[c] = {
            'locs': locs,
            'min_r': min_r,
            'max_r': max_r
        }

    def output_start_row(color):
        fr = first_appearance[color][0]
        if fr < 3:
            return 6
        elif fr == 3:
            return 7
        else:
            return 8

    output = [[0 for _ in range(cols)] for _ in range(rows)]

    for c in colors_ordered:
        info = color_info[c]
        start_r = output_start_row(c)
        for loc_r, loc_c in info['locs']:
            first_r = first_appearance[c][0]
            output_r = start_r + (loc_r - first_r)
            output_r = max(start_r, min(output_r, rows - 2))
            output[output_r][loc_c] = c

    for c in range(cols):
        output[rows-1][c] = 2

    return output

