def compute_output_row(first_row):
    """Compute the starting output row for a color whose first appearance is at first_row."""
    if first_row == 0:
        return 6
    elif first_row == 1:
        return 6
    elif first_row == 2:
        return 7
    elif first_row == 3:
        return 7
    elif first_row == 6:
        return 8
    elif first_row == 8:
        return 8
    elif first_row == 9:
        return 9
    else:
        # Fallback: linear interpolation
        return 6 + first_row

def output_row(first_row):
    """Get base output row for a given first appearance row."""
    mapping = {0: 6, 1: 6, 2: 7, 3: 7, 6: 8, 8: 8, 9: 9}
    return mapping.get(first_row, first_row)

def output_row_for_color(first_r, r):
    """Compute output row for a cell at row r where the color has first appearance at first_r."""
    base = output_row(first_r)
    return base + (r - first_r)

